void trace_sys_enter(void *data, struct pt_regs *regs, long id) {
    int syscall_nr = regs->syscall;
    struct ftrace_event_file *file;
    struct ftrace_raw_syscalls *entry;

    if (syscall_nr < 0 || syscall_nr >= __NR_syscalls)
        return;

    file = get_syscall_event_file(syscall_nr, 0);
    if (!file || !file->enabled)
        return;

    entry = ring_buffer_alloc_event(file->buffer, sizeof(*entry), file);
    if (!entry)
        return;

    entry->id = syscall_nr;
    entry->nr = syscall_nr;
    entry->args[0] = regs->di;
    entry->args[1] = regs->si;
    entry->args[2] = regs->dx;
    entry->args[3] = regs->cx;
    entry->args[4] = regs->r8;
    entry->args[5] = regs->r9;

    ring_buffer_commit_event(file->buffer, entry);
}

void handle_syscall_entry(void *data, struct pt_regs *regs, long id) {
    struct ftrace_event_file *file;
    struct ftrace_event_call *call;
    struct ring_buffer *buffer;
    struct ring_buffer_event *event;
    void *entry;

    unsigned long flags;
    int pc;

    id = (long) regs->ip;

    if (!id)
        return;

    call = find_event_call(id);
    if (!call || !call->enabled)
        return;

    file = data;
    buffer = file->ring_buffer;
    flags = raw_local_save_flags();
    pc = preempt_count();

    event = ring_buffer_lock_reserve(buffer, sizeof(*entry));
    if (!event)
        return;

    entry = ring_buffer_event_data(event);
    *(long *)entry = id;
    memcpy((unsigned char *)entry + sizeof(long), &regs->di, sizeof(regs->di));
    memcpy((unsigned char *)entry + sizeof(long) + sizeof(regs->di), &regs->si, sizeof(regs->si));
    memcpy((unsigned char *)entry + sizeof(long) + sizeof(regs->di) + sizeof(regs->si), &regs->dx, sizeof(regs->dx));
    memcpy((unsigned char *)entry + sizeof(long) + sizeof(regs->di) + sizeof(regs->si) + sizeof(regs->dx), &regs->cx, sizeof(regs->cx));
    memcpy((unsigned char *)entry + sizeof(long) + sizeof(regs->di) + sizeof(regs->si) + sizeof(regs->dx) + sizeof(regs->cx), &regs->r8, sizeof(regs->r8));
    memcpy((unsigned char *)entry + sizeof(long) + sizeof(regs->di) + sizeof(regs->si) + sizeof(regs->dx) + sizeof(regs->cx) + sizeof(regs->r8), &regs->r9, sizeof(regs->r9));

    ring_buffer_unlock_commit(buffer, event);
}

void trace_sys_enter(void *data, struct pt_regs *regs, long id)
{
    int idx = id / FTRACE_SYSCALLS_PER_EVENT;
    struct ftrace_event_file *file = &syscall_events[idx];
    struct trace_entry *entry;
    unsigned long flags, premp;
    struct ring_buffer_event *event;
    struct ring_buffer *buffer;

    if (!file->enabled)
        return;

    entry = (struct trace_entry *)__get_cpu_var(trace_buffer_entry);
    if (!entry)
        return;

    entry->type = TRACE_SYSCALL_ENTER;
    entry->syscall_id = id;
    entry->args = regs;

    buffer = file->ring_buffer;
    event = __ring_buffer_lock_reserve(buffer, sizeof(*entry), flags);
    if (!event)
        return;

    ring_buffer_put_entry(event, entry);
}

void handle_syscall_entry(void *data, struct pt_regs *regs, long id)
{
    int syscall_number = regs->ax;
    struct ftrace_event_file *event_file;
    struct trace_entry *entry;
    unsigned long flags, preempt_count;

    if (syscall_number < 0 || syscall_number >= NR_syscalls)
        return;

    event_file = get_syscall_event_file(syscall_number);
    if (!event_file || !event_file->enabled)
        return;

    flags = raw_local_save_flags();
    preempt_count = preempt_count();

    entry = trace_buffer_reserve(data, event_file, sizeof(*entry) + sizeof(u64));
    if (!entry)
        return;

    entry->type = TRACE_SYSCALL_ENTRY;
    entry->pid = task_pid_vnr(current);

    *(u64 *)((void *)entry + sizeof(*entry)) = syscall_number;

    for (int i = 0; i < 6; i++) {
        *(u64 *)((void *)entry + sizeof(*entry) + sizeof(u64) + i * sizeof(u64)) = regs->di + i;
    }

    trace_buffer_commit(data, event_file, entry, sizeof(*entry) + 7 * sizeof(u64));
}

void handle_syscall_entry(void *data, struct pt_regs *regs, long id) {
    struct ftrace_event_file *file;
    struct ftrace_raw_syscall *entry;
    unsigned long flags;
    int cnt;

    id = (long) syscall_metadata(id);
    if (!id)
        return;

    file = find_event_file(TRACE_SUBSYSTEM_SYSCALLS, "sys_enter");
    if (!file || !file->enabled)
        return;

    flags = hardirq_save();
    cnt = preempt_count();

    entry = __trace_wakeup(file, 0);
    if (entry) {
        __trace_iter_do_update(entry, file, regs, id);
        __trace_commit(entry);
    }

    hardirq_restore(flags);
    preempt_count_set(cnt);
}
